import unittest
from candidate import largest_prime_factor, is_prime

class TestLargestPrimeFactor(unittest.TestCase):
    def test_largest_prime_factor_normalcase(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_largest_prime_factor_prime(self):
        self.assertEqual(largest_prime_factor(7), 7)

    def test_largest_prime_factor_small_number(self):
        self.assertEqual(largest_prime_factor(5), 5)

    def test_largest_prime_factor_zero(self):
        self.assertRaises(TypeError, largest_prime_factor, 0)

    def test_largest_prime_factor_negative(self):
        self.assertRaises(TypeError, largest_prime_factor, -1)

    def test_largest_prime_factor_float(self):
        self.assertRaises(TypeError, largest_prime_factor, 2.5)

    def test_is_prime_true(self):
        self.assertTrue(is_prime(7))

    def test_is_prime_false(self):
        self.assertFalse(is_prime(10))

    def test_is_prime_one(self):
        self.assertFalse(is_prime(1))

    def test_is_prime_zero(self):
        self.assertFalse(is_prime(0))

if __name__ == '__main__':
    unittest.main()
